def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    if n == 2:
        opp = history[1][1]
        return 'D' if opp == 'D' else 'C'

    opp_d = 0
    my_d = 0
    opp_d_last10 = 0
    my_d_last10 = 0
    opp_d_last4 = 0
    opp_c_last4 = 0
    alt = 0
    for i in range(n):
        m, o = history[i]
        if o == 'D':
            opp_d += 1
            if i >= n - 10:
                opp_d_last10 += 1
            if i >= n - 4:
                opp_d_last4 += 1
        if m == 'D':
            my_d += 1
            if i >= n - 10:
                my_d_last10 += 1
        if o == 'C' and i >= n - 4:
            opp_c_last4 += 1
    last_me, last_opp = history[-1]

    # Endgame: if opponent mainly cooperative, squeeze last rounds
    if n >= 96:
        # use last few rounds to defect when opponent likely to cooperate
        if opp_d * 3 < n:
            return 'D'
        if last_opp == 'C' and (n < 2 or history[-2][1] == 'C'):
            return 'D'
        if last_opp == 'C':
            return 'D'
        return 'C'

    opp_rate = opp_d / float(n)

    # Detect alternating C/D (retaliation loop) - try to break with C
    if n >= 4:
        o1 = history[-1][1]
        o2 = history[-2][1]
        o3 = history[-3][1]
        o4 = history[-4][1]
        if o1 != o2 and o2 != o3 and o3 != o4:
            # opponent alternating
            if last_opp == 'D':
                return 'C'
            return 'C'

    # Mutual cooperation established: keep it
    if opp_d_last10 == 0 and my_d_last10 == 0 and n >= 5:
        return 'C'

    # Opponent mostly defecting late
    if opp_rate > 0.6 and n >= 15:
        return 'D'

    # Opponent very cooperative: cooperate, occasional probing only pre-endgame
    if opp_d_last10 <= 1 and opp_rate < 0.15:
        return 'C'

    # Heavy recent defection: punish briefly
    if opp_d_last4 >= 3:
        return 'D'

    # Isolated defection: retaliate once then forgive
    if last_opp == 'D':
        if last_me == 'C':
            # was sucker: defect once
            return 'D'
        # both defected: try to return to cooperation
        if opp_d_last4 <= 2 and opp_rate < 0.4:
            return 'C'
        if rng.random() < 0.6:
            return 'C'
        return 'D'

    # Opponent cooperated last round
    if opp_rate > 0.4 and opp_d > my_d + 1 and n < 80:
        # opponent defecting more than us, but currently cooperating: opportunistic defect
        if rng.random() < 0.25:
            return 'D'
    return 'C'
